"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[13844],{46365:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>i,contentTitle:()=>h,default:()=>c,frontMatter:()=>r,metadata:()=>a,toc:()=>d});var o=n(31085),s=n(71184);const r={sidebar_position:9,slug:"/bible/Apocalypse/Apocalypse_9",title:"Apocalypse 9",hide_table_of_contents:!0},h="Apocalypse",a={id:"bible/Apocalypse/Apocalypse 9",title:"Apocalypse 9",description:"Chapter 9",source:"@site/docs/bible/Apocalypse/Apocalypse 9.md",sourceDirName:"bible/Apocalypse",slug:"/bible/Apocalypse/Apocalypse_9",permalink:"/bibleNotes/docs/bible/Apocalypse/Apocalypse_9",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Apocalypse/Apocalypse 9.md",tags:[],version:"current",sidebarPosition:9,frontMatter:{sidebar_position:9,slug:"/bible/Apocalypse/Apocalypse_9",title:"Apocalypse 9",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Apocalypse 8",permalink:"/bibleNotes/docs/bible/Apocalypse/Apocalypse_8"},next:{title:"Apocalypse 10",permalink:"/bibleNotes/docs/bible/Apocalypse/Apocalypse_10"}},i={},d=[{value:"Chapter 9",id:"chapter-9",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:n}=t;return n||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.h1,{id:"apocalypse",children:"Apocalypse"}),"\n",(0,o.jsx)(t.h2,{id:"chapter-9",children:"Chapter 9"}),"\n",(0,o.jsx)(t.p,{children:"Locusts come forth from the bottomless pit.  The vision of the army of horsemen."}),"\n",(0,o.jsx)(n,{verse:1,children:"And the fifth angel sounded the trumpet: and I saw a star fall from heaven upon the earth. And there was given to him the key of the bottomless pit."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: A star full...This may mean the fall and apostasy of great and learned men from the true faith. Or a whole nation falling into error and separating from the church, not having the sign of God in their foreheads. And there was given to him the key of the bottomless\r\nNote 2: pit...That is, to the angel, not to the fallen star. To this angel was given the power, which is here signified by a key, of opening hell."})}),"\n",(0,o.jsx)(n,{verse:2,children:"And he opened the bottomless pit: and the smoke of the pit arose, as the smoke of a great furnace. And the sun and the air were darkened with the smoke of the pit."}),"\n",(0,o.jsx)(n,{verse:3,children:"And from the smoke of the pit there came out locusts upon the earth. And power was given to them, as the scorpions of the earth have power."}),"\n",(0,o.jsx)(t.admonition,{type:"note",children:(0,o.jsx)(t.p,{children:"Note 1: There came out locusts...These may be devils in Antichrist's time, having the appearance of locusts, but large and monstrous, as here described. Or they may be real locusts, but of an extraordinary size and monstrous shape, such as were never before seen on earth, sent to torment those who have not the sign (or seal) of God on their foreheads. Some commentators by these locusts understand heretics, and especially those heretics, that sprung from Jews, and with them denied the divinity of Jesus Christ; as Theodotus, Praxeas, Noetus, Paul of Samosata, Sabellius, Arius, etc. These were great enemies of the Christian religion; they tormented and infected the souls of men, stinging them like scorpions, with the poison of their heresies. Others have explained these locusts, and other animals, mentioned in different places throughout this sacred and mystical book, in a most absurd, fanciful, and ridiculous manner; they make Abaddon the Pope, and the locusts to be friars mendicant, etc. Here it is thought proper, not to enter into any controversy upon that subject, as the inventors of these fancies have been already answered, and fully refuted by many controvertists: besides, those who might be inposed on by such chimerical writers, are in these days much better informed."})}),"\n",(0,o.jsx)(n,{verse:4,children:"And it was commanded them that they should not hurt the grass of the earth nor any green thing nor any tree: but only the men who have not the sign of God on their foreheads."}),"\n",(0,o.jsx)(n,{verse:5,children:"And it was given unto them that they should not kill them: but that they should torment them five months. And their torment was as the torment of a scorpion when he striketh a man."}),"\n",(0,o.jsx)(n,{verse:6,children:"And in those days, men shall seek death and shall not find it. And they shall desire to die: and death shall fly from them."}),"\n",(0,o.jsx)(n,{verse:7,children:"And the shapes of the locusts were like unto horses prepared unto battle. And on their heads were, as it were, crowns like gold: and their faces were as the faces of men."}),"\n",(0,o.jsx)(n,{verse:8,children:"And they had hair as the hair of women: and their teeth were as lions."}),"\n",(0,o.jsx)(n,{verse:9,children:"And they had breastplates as breastplates of iron: and the noise of their wings was as the noise of chariots and many horses running to battle."}),"\n",(0,o.jsx)(n,{verse:10,children:"And they had tails like to scorpions: and there were stings in their tails. And their power was to hurt men, five months. And they had over them"}),"\n",(0,o.jsx)(n,{verse:11,children:"A king, the angel of the bottomless pit (whose name in Hebrew is Abaddon and in Greek Apollyon, in Latin Exterminans)."}),"\n",(0,o.jsx)(n,{verse:12,children:"One woe is past: and behold there come yet two woes more hereafter."}),"\n",(0,o.jsx)(n,{verse:13,children:"And the sixth angel sounded the trumpet: and I heard a voice from the four horns of the golden altar which is before the eyes of God,"}),"\n",(0,o.jsx)(n,{verse:14,children:"Saying to the sixth angel who had the trumpet: Loose the four angels who are bound in the great river Euphrates."}),"\n",(0,o.jsx)(n,{verse:15,children:"And the four angels were loosed, who were prepared for an hour, and a day, and a month, and a year: for to kill the third part of men."}),"\n",(0,o.jsx)(n,{verse:16,children:"And the number of the army of horsemen was twenty thousand times ten thousand. And I heard the number of them."}),"\n",(0,o.jsx)(n,{verse:17,children:"And thus I saw the horses in the vision. And they that sat on them had breastplates of fire and of hyacinth and of brimstone. And the heads of the horses were as the heads of lions: and from their mouths proceeded fire and smoke and brimstone."}),"\n",(0,o.jsx)(n,{verse:18,children:"And by these three plagues was slain the third part of men, by the fire and by the smoke and by the brimstone which issued out of their mouths."}),"\n",(0,o.jsx)(n,{verse:19,children:"For the power of the horses is in their mouths and in their tails. For, their tails are like to serpents and have heads: and with them they hurt."}),"\n",(0,o.jsx)(n,{verse:20,children:"And the rest of the men, who were not slain by these plagues, did not do penance from the works of their hands, that they should not adore devils and idols of gold and silver and brass and stone and wood, which neither can see nor hear nor walk:"}),"\n",(0,o.jsx)(n,{verse:21,children:"Neither did they penance from their murders nor from their sorceries nor from their fornication nor from their thefts."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(l,{...e})}):l(e)}},71184:(e,t,n)=>{n.d(t,{R:()=>h,x:()=>a});var o=n(14041);const s={},r=o.createContext(s);function h(e){const t=o.useContext(r);return o.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:h(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);